// AniList: وصف الأنمي + التقييم (المصدر الأول: أدق وأسرع من Jikan)
ipcMain.handle('anilist:desc', async (_e, names) => {
  const nz = (x) => String(x || '').toLowerCase().replace(/[^a-z0-9؀-ۿ]+/g, '');
  const same = (a, b) => { if (!a || !b) return false; if (a === b) return true; const [sh, lo] = a.length < b.length ? [a, b] : [b, a]; return sh.length >= 6 && lo.includes(sh) && sh.length / lo.length >= 0.7; };
  const list = [...new Set((names || []).map((n) => String(n || '').trim()).filter(Boolean))].slice(0, 3);
  const want = list.map(nz).filter(Boolean);
  const query = 'query($s:String){Page(perPage:8){media(search:$s,type:ANIME,sort:SEARCH_MATCH){id title{romaji english native} synonyms description(asHtml:false) averageScore siteUrl}}}';
  for (const n of list) {
    for (let k = 0; k < 2; k++) {
      let r;
      try {
        r = await fetch('https://graphql.anilist.co', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify({ query, variables: { s: n.slice(0, 200) } }), signal: AbortSignal.timeout(9000) });
      } catch { break; }
      if (r.status === 429) { await new Promise((ok) => setTimeout(ok, 1500)); continue; }
      if (!r.ok) break;
      const j = await r.json();
      const media = (j.data && j.data.Page && j.data.Page.media) || [];
      const a = media.find((x) => [x.title && x.title.romaji, x.title && x.title.english, x.title && x.title.native, ...(x.synonyms || [])].map(nz).some((t) => want.some((w) => same(t, w))));
      if (a && a.description) {
        const text = String(a.description).replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]+>/g, '').replace(/\(Source:[^)]*\)/gi, '').replace(/\[Written by[^\]]*\]/gi, '').replace(/\n{2,}/g, '\n').trim();
        if (text) return { description: text, score: a.averageScore ? (a.averageScore / 10).toFixed(1) : '', url: a.siteUrl || '' };
      }
      break;
    }
  }
  return null;
});

// AniList: جدول الحلقات القادمة (7 أيام) — الأنمي اللي غادي يخرج
ipcMain.handle('anilist:schedule', async (_e, days) => {
  const from = Math.floor(Date.now() / 1000), to = from + Math.min(Math.max(Number(days) || 7, 1), 14) * 86400;
  const query = 'query($from:Int,$to:Int,$page:Int){Page(page:$page,perPage:50){pageInfo{hasNextPage} airingSchedules(airingAt_greater:$from,airingAt_lesser:$to,sort:TIME){airingAt episode media{id format countryOfOrigin isAdult title{romaji english native} coverImage{large medium}}}}}';
  const out = [];
  for (let page = 1; page <= 6; page++) {
    const r = await fetch('https://graphql.anilist.co', {
      method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ query, variables: { from, to, page } }), signal: AbortSignal.timeout(12000)
    });
    if (r.status === 429) { await new Promise((ok) => setTimeout(ok, 1500)); page--; continue; }
    if (!r.ok) throw new Error('AniList HTTP ' + r.status);
    const j = await r.json();
    const P = j.data && j.data.Page; if (!P) break;
    for (const s of P.airingSchedules || []) {
      const md = s.media; if (!md || md.isAdult || md.countryOfOrigin !== 'JP' || !/^(TV|TV_SHORT|ONA|OVA|MOVIE|SPECIAL)$/.test(md.format || '')) continue;
      out.push({ at: s.airingAt, ep: s.episode, id: md.id, format: md.format, title: md.title.english || md.title.romaji || md.title.native || '', romaji: md.title.romaji || '', img: (md.coverImage && (md.coverImage.large || md.coverImage.medium)) || '' });
    }
    if (!P.pageInfo || !P.pageInfo.hasNextPage) break;
  }
  return out;
});

// AniList: آخر حلقات عُرضت (آخر أيام) — مصدر بلا Cloudflare: يضمن ظهور الأنمي المترجم (Black Clover / Blue Box…) فـ «آخر الحلقات»
ipcMain.handle('anilist:recent', async (_e, days) => {
  const to = Math.floor(Date.now() / 1000), from = to - Math.min(Math.max(Number(days) || 4, 1), 10) * 86400;
  const query = 'query($from:Int,$to:Int,$page:Int){Page(page:$page,perPage:50){pageInfo{hasNextPage} airingSchedules(airingAt_greater:$from,airingAt_lesser:$to,sort:TIME_DESC){airingAt episode media{id format countryOfOrigin isAdult title{romaji english native} coverImage{large medium}}}}}';
  const out = [], seen = new Set(); let retry = 0;
  for (let page = 1; page <= 4; page++) {
    const r = await fetch('https://graphql.anilist.co', {
      method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ query, variables: { from, to, page } }), signal: AbortSignal.timeout(12000)
    });
    if (r.status === 429 && retry++ < 3) { await new Promise((ok) => setTimeout(ok, 1500)); page--; continue; }
    if (!r.ok) throw new Error('AniList HTTP ' + r.status);
    const j = await r.json();
    const P = j.data && j.data.Page; if (!P) break;
    for (const s of P.airingSchedules || []) {
      const md = s.media; if (!md || md.isAdult || md.countryOfOrigin !== 'JP' || !/^(TV|TV_SHORT|ONA)$/.test(md.format || '') || seen.has(md.id)) continue;
      seen.add(md.id);   // مرتبين من الأحدث: أول ظهور = أعلى حلقة
      out.push({ at: s.airingAt, ep: s.episode, id: md.id, title: md.title.english || md.title.romaji || md.title.native || '', romaji: md.title.romaji || '', img: (md.coverImage && (md.coverImage.large || md.coverImage.medium)) || '' });
    }
    if (!P.pageInfo || !P.pageInfo.hasNextPage) break;
  }
  return out;
});

// AniList: تصنيفات حقيقية (genre / tag) — الأنمي مرتب بالشعبية، وصفحة بصفحة
ipcMain.handle('anilist:genre', async (_e, o) => {
  o = o || {};
  const fm = ({ SERIES: ['TV', 'TV_SHORT', 'ONA'], MOVIE: ['MOVIE'], OVA: ['OVA'], SPECIAL: ['SPECIAL'] })[o.type] || ['TV', 'TV_SHORT', 'ONA'];
  const sort = /^[A-Z_]+$/.test(o.sort || '') ? o.sort : 'POPULARITY_DESC';
  const decl = ['$page:Int', '$formats:[MediaFormat]', '$sort:[MediaSort]'], args = ['type:ANIME', 'isAdult:false', 'countryOfOrigin:JP', 'format_in:$formats', 'sort:$sort'];
  const vars = { page: Math.max(1, Number(o.page) || 1), formats: fm, sort: [sort] };
  if (o.kind === 'g') { decl.push('$genre:String'); args.push('genre:$genre'); vars.genre = String(o.value || ''); }
  else if (o.kind === 't') { decl.push('$tag:String'); args.push('tag:$tag'); vars.tag = String(o.value || ''); }
  if (o.status === 'RELEASING') { decl.push('$status:MediaStatus'); args.push('status:$status'); vars.status = 'RELEASING'; }
  const query = 'query(' + decl.join(',') + '){Page(page:$page,perPage:36){pageInfo{hasNextPage} media(' + args.join(',') + '){id format averageScore episodes title{romaji english native} coverImage{large medium}}}}';
  let r = null;
  for (let t = 0; t < 3; t++) {
    r = await fetch('https://graphql.anilist.co', { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify({ query, variables: vars }), signal: AbortSignal.timeout(12000) });
    if (r.status !== 429) break;
    await new Promise((ok) => setTimeout(ok, 1500));
  }
  if (!r.ok) throw new Error('AniList HTTP ' + r.status);
  const j = await r.json(), P = j.data && j.data.Page;
  if (!P) throw new Error('AniList: رد فارغ');
  return {
    next: !!(P.pageInfo && P.pageInfo.hasNextPage),
    list: (P.media || []).map((md) => ({ id: md.id, format: md.format || '', score: md.averageScore || 0, eps: md.episodes || 0, title: md.title.english || md.title.romaji || md.title.native || '', romaji: md.title.romaji || '', img: (md.coverImage && (md.coverImage.large || md.coverImage.medium)) || '' })).filter((x) => x.title && x.img)
  };
});

